from fastapi import Depends, FastAPI

def get_db():
    db = "SessaoBanco"  # Simula abertura de conexão
    try:
        yield db
    finally:
        pass  # Fecha a conexão após a resposta!

@app.get("/perfil")
async def perfil(db = Depends(get_db)):
    return {"conexao": db}

